module prime_divisible(\n    input [3:0] b, \n    input [3:0] d, \n    output reg yes_no\n);\n    always @(*) begin\n        case (d)\n            4'd2  : yes_no = (b[0] == 1'b0);\n            4'd3  : yes_no = (b == 4'd0 || b == 4'd3 || b == 4'd6 || b == 4'd9 || b == 4'd12 || b == 4'd15);\n            4'd5  : yes_no = (b == 4'd0 || b == 4'd5 || b == 4'd10 || b == 4'd15);\n            4'd7  : yes_no = (b == 4'd0 || b == 4'd7 || b == 4'd14);\n            4'd11 : yes_no = (b == 4'd0 || b == 4'd11);\n            4'd13 : yes_no = (b == 4'd0 || b == 4'd13);\n            default: yes_no = 1'b0;\n        endcase\n    end\nendmodule